import {connectionCards} from './focus-experience.mjs';
import {COURSE} from './core.mjs';
import {proofIsCurrent} from './operations.mjs';
import {queueFor,caseLabel} from './focus-model.mjs';
import {activityKind} from './focus-activity.mjs';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function icon(name){const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',arrow:'M5 12h14 M13 6l6 6-6 6',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 12l3 3 5-6',check:'M5 12l4 4L19 6',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',refresh:'M20 7a9 9 0 1 0 1 9 M20 2v6h-6',book:'M4 3h12a4 4 0 0 1 4 4v14H8a4 4 0 0 1-4-4z M4 16h16 M8 7h8 M8 11h5'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;}
export function navigation(screen){return `<nav class="workspace-nav" aria-label="Workspace navigation">${[['cases','grid','Recovery desk'],['activity','clock','Activity'],['connections','link','Connections']].map(([id,i,label])=>`<button data-screen="${id}" ${screen===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}<a href="guide.html">Build guide ↗</a></nav>`;}
function money(cents){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);}
function age(s){const minutes=Math.max(0,Math.floor((Date.now()-Date.parse(s.paidAt||s.createdAt))/60000));return minutes<1?'Just now':minutes<60?minutes+'m ago':minutes<1440?Math.floor(minutes/60)+'h ago':Math.floor(minutes/1440)+'d ago';}
function eventItems(cases){return cases.flatMap(s=>s.events.map(event=>({...event,id:s.id,name:s.customerName}))).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));}
export function activityView(cases,compact=false){const events=eventItems(cases).slice(0,compact?4:40);return `<div class="activity-feed">${events.length?events.map(ev=>`<button class="activity-event" data-case="${e(ev.id)}" data-activity-kind="${activityKind(ev.what)}"><span class="event-dot"></span><span><strong>${e(ev.name)}</strong><span>${e(ev.what)}</span><small>${e(new Date(ev.at).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}))} · ${e(ev.id)}</small></span>${icon('arrow')}</button>`).join(''):'<p>No recovery activity yet. Open a case to begin.</p>'}</div>`;}
export function workspaceView({cases,queue,search,sort,backend,busy,screen}){const counts={attention:0,investigating:0,resolved:0};cases.forEach(s=>counts[queueFor(s)]++);const names={attention:'Needs attention',investigating:'Investigating',resolved:'Resolved'};const recommended=cases.find(s=>['unverified','verifying'].includes(s.phase))||cases.find(s=>['rehearsed','approved'].includes(s.phase))||cases.find(s=>queueFor(s)==='attention')||cases.find(s=>queueFor(s)==='investigating');
const recommendedDetail=recommended?.phase==='rehearsed'?'A correction preview is ready for your approval.':recommended?.phase==='approved'?'Your approved change is ready to apply and verify.':recommended?.writes&&!proofIsCurrent(recommended)?'Access changed; verify the lesson before reporting success.':recommended?'Review the purchase evidence before any change.':'';
const filtered=cases.filter(s=>queueFor(s)===queue&&`${s.customerName} ${s.id} ${COURSE.name}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==='customer'?a.customerName.localeCompare(b.customerName):sort==='newest'?Date.parse(b.paidAt||b.createdAt)-Date.parse(a.paidAt||a.createdAt):Date.parse(a.paidAt||a.createdAt)-Date.parse(b.paidAt||b.createdAt));
const intro=`<div class="desk-heading"><div><span class="eyebrow">STILLFRAME ACADEMY / WORKSPACE</span><h1>${screen==='activity'?'Every step, accounted for.':screen==='connections'?'Know what’s connected.':'Let’s get your customers back in.'}</h1><p>${screen==='activity'?'A record of reviews, approvals, corrections, and checked outcomes.':screen==='connections'?'A clear view of the services behind each recovery.':'The right case. The evidence you need. One clear next step.'}</p></div><button class="button" data-action="refresh" ${busy?'disabled':''}>${icon('refresh')}${busy?'Refreshing…':'Refresh records'}</button></div>`;
if(screen==='activity')return `${intro}<section class="surface activity-page"><div class="section-head"><h2>Recovery activity</h2><span class="subtle">Most recent first · up to 40 events</span></div>${activityView(cases)}</section>`;
if(screen==='connections')return `${intro}${connectionCards(cases,backend,window.COURSELATCH_RUNTIME||{})}`;
return `${intro}<div class="overview"><section class="start-card"><div class="start-copy"><span class="eyebrow">${recommended?'YOUR NEXT BEST STEP':'ALL CHECKED'}</span><h2>${recommended?`${e(recommended.customerName)} is waiting on a clear outcome.`:'Your recovery queue is clear.'}</h2><p>${recommended?e(caseLabel(recommended))+'. '+e(recommendedDetail):(cases.length?'Every case in this workspace has a current access verification.':'No cases yet. Use + New case to start with a purchase.')}</p>${recommended?`<button class="button" data-case="${e(recommended.id)}" ${busy?'disabled':''}>Review ${e(recommended.customerName)}’s case ${icon('arrow')}</button>`:''}<a class="queue-jump" href="#recovery-queue">View the queue ↓</a><span class="start-reason">${icon('shield')} ${recommended?.writes?'Verification first. No repeat grant.':'You approve. We verify.'}</span></div><div class="access-visual" aria-hidden="true"><div class="visual-payment"><img src="assets/paypal-mark.svg" alt=""><span>Payment record</span><b>01</b></div><div class="visual-track"><i></i><i></i><span>${icon('shield')}</span><i></i><i></i></div><div class="visual-access">${icon('book')}<span>Purchased access</span><b>02</b></div><small>FOLLOW THE PAYMENT TO THE OUTCOME</small></div></section><section class="outcome-card"><span class="eyebrow">VERIFIED RECOVERIES</span><div class="outcome-number">${counts.resolved}<span>of ${cases.length} cases</span></div><div class="outcome-track"><span style="width:${cases.length?counts.resolved/cases.length*100:0}%"></span></div><p>${counts.resolved?money(cases.filter(proofIsCurrent).reduce((n,s)=>n+s.order.amount,0))+' in purchases with verified access':'Your first verified recovery starts with a case review.'}</p><span class="subtle">Current workspace · ${backend?'server demo':'sample data'}</span></section></div><div class="desk-columns"><section id="recovery-queue" class="surface queue-surface"><div class="section-head"><div><h2>Recovery queue</h2><span class="subtle">${cases.length-counts.resolved} open cases · Each correction needs your approval</span></div><span class="queue-count">${cases.length}</span></div><div class="queue-tabs" aria-label="Case queues">${Object.entries(names).map(([id,label])=>`<button data-queue="${id}" aria-pressed="${queue===id}">${label}<b>${counts[id]}</b></button>`).join('')}</div><div class="queue-tools"><label class="search-wrap"><span aria-hidden="true">⌕</span><input type="search" class="search" aria-label="Search cases" placeholder="Search customer or case" value="${e(search)}"></label><select aria-label="Sort cases"><option value="oldest" ${sort==='oldest'?'selected':''}>Oldest first</option><option value="newest" ${sort==='newest'?'selected':''}>Newest first</option><option value="customer" ${sort==='customer'?'selected':''}>Customer A–Z</option></select></div><div class="list-head"><span>Customer / purchase</span><span>Next step</span><span>Payment</span><span></span></div><div class="case-list">${filtered.length?filtered.map((s,i)=>`<button class="case-row" data-case="${e(s.id)}" ${busy?'disabled':''}><span class="person"><span class="initial tone-${i%4}">${e(s.customerName.slice(0,1))}</span><span><strong>${e(s.customerName)}</strong><small>${e(s.id)} · ${age(s)}</small></span></span><span class="issue"><span class="case-status ${queue==='resolved'?'success':queue==='investigating'?'waiting':''}"><i></i>${e(caseLabel(s))}</span><small>Light & Story Workshop</small></span><span class="amount"><strong>${money(s.order.amount)}</strong><small>${s.capture?.status==='COMPLETED'?'Completed':'Pending'}</small></span><span class="next" aria-label="Open case">${icon('arrow')}</span></button>`).join(''):`<div class="empty"><span class="empty-icon">${icon(queue==='resolved'?'shield':'check')}</span><strong>${search?'No matching cases.':queue==='resolved'?'The next outcome starts here.':'Nothing needs attention here.'}</strong><p>${search?'Try another customer name or case number.':queue==='resolved'?'Cases appear here only after access is verified.':'Choose another queue to continue reviewing.'}</p>${search?'<button class="button" data-action="clear-search">Clear search</button>':'<button class="button" data-action="new-case">Start a new case</button>'}</div>`}</div><div class="queue-footer"><span>${filtered.length} ${filtered.length===1?'case':'cases'} in this view</span><span>${icon('shield')} Approval required for every grant</span></div></section><aside class="desk-rail"><section class="surface team-panel"><div class="section-head"><h2>Your recovery team</h2><span class="team-spark">${icon('spark')}</span></div><p>Four perspectives.<br>One evidence-backed recommendation.</p><div class="team-mini">${[['L','Ledger','Checks the payment'],['R','Relay','Follows the event trail'],['P','Patch','Plans the smallest fix'],['P','Prism','Challenges & verifies']].map(([letter,name,role],i)=>`<div><span class="specialist-avatar specialist-${i}">${letter}</span><span><strong>${name}</strong><small>${role}</small></span></div>`).join('')}</div><div class="team-note">${backend?'See each case for the analysis method used.':'Scripted specialists in this demo.'} Findings and cited records appear inside the case.</div></section><section class="surface recent-panel"><div class="section-head"><h2>Recent activity</h2><button class="text-button" data-screen="activity">View all ↗</button></div>${activityView(cases,true)}</section></aside></div>`;
}
export function accessJourney(s){const verified=proofIsCurrent(s);return `<div class="access-journey"><div class="journey-node ${s.capture?.status==='COMPLETED'?'complete':''}"><span>${icon('check')}</span><div><small>01 / PAYMENT</small><strong>${s.capture?.status==='COMPLETED'?'Completed':'Needs confirmation'}</strong></div></div><i></i><div class="journey-node ${s.entitlement.active?'complete':''}"><span>${icon('book')}</span><div><small>02 / ACCESS</small><strong>${s.entitlement.active?'Entitlement active':'Not yet restored'}</strong></div></div><i></i><div class="journey-node ${verified?'complete':''}"><span>${icon('shield')}</span><div><small>03 / OUTCOME</small><strong>${verified?'Verified':'Not yet verified'}</strong></div></div></div>`;}
